"""Language membership oracle: walk the compiled image vs direct semantics."""
import itertools, sys
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from syntax import parse, MATCH, STARTSWITH, ENDSWITH, CONTAINS, AND, OR, NOT, ALLOW, DROP
from ebpf.create_dfa import create, registry_columns
D=4294967295

def ev(node,w):
    k=node[0]
    if k==MATCH: return w==node[1]
    if k==STARTSWITH:
        p=node[1]; return len(w)>=len(p) and w[:len(p)]==p
    if k==ENDSWITH:
        p=node[1]; return len(w)>=len(p) and (not p or w[-len(p):]==p)
    if k==CONTAINS:
        p=node[1]
        if not p: return True
        m=len(p)
        return any(w[i:i+m]==p for i in range(len(w)-m+1))
    if k==AND: return ev(node[1],w) and ev(node[2],w)
    if k==OR: return ev(node[1],w) or ev(node[2],w)
    return not ev(node[1],w)

def check_lang(text, reg, maxlen, verbose=False):
    cols,colmap=registry_columns(reg)
    img=create(text,cols,colmap)
    res=parse(text)
    names=res.names
    cols_of=[colmap.get(names[i],-1) for i in range(len(names))]
    def ren(n):
        k=n[0]
        if k<=CONTAINS: return (k,tuple(cols_of[i] for i in n[1]),None)
        if k==NOT: return (k,ren(n[1]),None)
        return (k,ren(n[1]),ren(n[2]))
    rules=[(ren(n),a) for n,a in res.rules]
    allow=[n for n,a in rules if a==ALLOW]; drop=[n for n,a in rules if a==DROP]
    bad=0; total=0
    for L in range(maxlen+1):
        for w in itertools.product(range(len(cols)),repeat=L):
            total+=1
            want = any(ev(n,w) for n in allow) and not any(ev(n,w) for n in drop)
            s=0; ok=True
            for c in w:
                s=img.rows[s][c]
                if s==D: ok=False; break
            got = ok and img.accept[s]
            if got!=want:
                bad+=1
                if verbose and bad<4: print('  word',w,'got',got,'want',want)
    return bad,total
PYEOF
